import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
/*eslint-disable*/
import EditCategories from "@/components/Asset/Popups/EditCategories.vue";
import AssetVerfication from "@/components/Asset/Popups/AssetVerfication.vue";
import SnackBar from "@/components/SnackBar.vue";
import DeleteCategories from "@/components/Asset/Popups/DeleteCategories.vue";
import AddSubcategories from "@/components/Asset/Popups/AddSubcategories.vue";
import AddCategories from "@/components/Asset/Popups/AddCategories.vue";
import { get_asset_sub_categories } from "@/mixins/GetAssetSubCategories.js";
import { asset_categories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    SnackBar,
    DeleteCategories,
    EditCategories,
    AssetVerfication,
    AddSubcategories,
    AddCategories
  },
  emits: ['backAction'],
  mixins: [get_asset_sub_categories],
  data() {
    return {
      SnackBarComponent: {},
      categoriesEddition: false,
      categoriesdeletion: false,
      tableLoading: false,
      componentCheck: 0,
      categoriesItem: {},
      verficationAsset: false,
      categoriessubAddition: false,
      categoriesHeaders: [{
        title: "Prefix",
        key: "category_prefix",
        sortable: false
      }, {
        title: "Name",
        key: "category_name",
        sortable: false
      }, {
        title: "#No.of Subcategories",
        key: "sub_category_count",
        sortable: false
      }, {
        title: "Depreciation(%)",
        key: "category_depriciation",
        sortable: false
      },
      // {
      //   title: "Verfication Date",
      //   key: "category_verification_date",
      //   sortable: false,
      // },

      {
        title: "Created By",
        key: "category_created_by_name",
        sortable: false
      }, {
        title: "Actions",
        key: "actions",
        sortable: false
      }],
      categoriesRecords: [],
      fixed: false,
      expanded: [],
      singleExpand: true,
      allSubCategories: [],
      categoryPrefix: "",
      subcategoryName: "",
      rowInfo: {},
      categoriesAddition: false,
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      windowHeight: 0,
      searchQuery: "",
      filteredCategoriesRecords: []
    };
  },
  computed: {
    totalCount() {
      return this.filteredCategoriesRecords.length;
    },
    pageCount() {
      return Math.ceil(this.filteredCategoriesRecords.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  async created() {
    this.allSubCategories = [];
    await this.fetch_categories();
    await this.get_asset_sub_categories();
    this.allSubCategories = this.assetSubCategories;
  },
  mounted() {
    this.updateWindowHeight();
    window.addEventListener('resize', this.updateWindowHeight);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.updateWindowHeight);
  },
  methods: {
    add_categories() {
      this.componentCheck = 5;
      this.categoriesAddition = true;
    },
    convert_to_uppercase() {
      this.categoryPrefix = this.categoryPrefix.toUpperCase();
    },
    get_date(val) {
      const d = new Date(parseInt(val));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
    },
    handle_row_click(item) {
      this.componentCheck = 4;
      this.categoriessubAddition = true;
      this.rowInfo = item;
    },
    open_veficationDailog(item) {
      this.componentCheck = 3;
      this.categoriesItem = item;
      this.verficationAsset = true;
    },
    open_editDailog(item) {
      this.categoriesItem = item;
      this.componentCheck = 2;
      this.categoriesEddition = true;
    },
    open_deleteDailog(item) {
      this.categoriesItem = item;
      this.componentCheck = 1;
      this.categoriesdeletion = true;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.categoriesdeletion = false;
      this.categoriesEddition = false;
      this.verficationAsset = false;
      this.categoriesAddition = false;
      this.fetch_categories();
    },
    async fetch_categories() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(asset_categories, {
          input: {
            user_email_id: data.user.user_email_id,
            action_type: "LIST_CATEGORY"
          }
        }));
        var response = JSON.parse(result.data.asset_categories);
        //  console.log(response);
        this.categoriesRecords = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.categoriesRecords = response.data;
          this.filterCategories();
          this.tableLoading = false;
          this.updatePageItems();
        } else {
          this.categoriesRecords = [];
          this.filteredCategoriesRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        this.categoriesRecords = [];
        this.filteredCategoriesRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    onSearchChange() {
      this.currentPage = 1;
      this.filterCategories();
      this.updatePageItems();
    },
    filterCategories() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        this.filteredCategoriesRecords = this.categoriesRecords;
      } else {
        const query = this.searchQuery.toLowerCase().trim();
        this.filteredCategoriesRecords = this.categoriesRecords.filter(category => {
          return category.category_name && category.category_name.toLowerCase().includes(query) || category.category_prefix && category.category_prefix.toLowerCase().includes(query) || category.category_created_by_name && category.category_created_by_name.toLowerCase().includes(query) || category.category_description && category.category_description.toLowerCase().includes(query) || category.category_depriciation && category.category_depriciation.toString().includes(query) || category.sub_category_count && category.sub_category_count.toString().includes(query);
        });
      }
    },
    updatePageItems() {
      const startIndex = (this.currentPage - 1) * this.itemsPerPage;
      const endIndex = startIndex + this.itemsPerPage;
      this.paginatedItems = this.filteredCategoriesRecords.slice(startIndex, endIndex);
    },
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 310; // Adjust for header and toolbar
    }
  }
};
